// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(this)); // avoid owner being set to test contract
        // add a reward token to ensure the contract is fully initialized
        c.addReward(address(0x1));

        // try to transfer ownership to a non-zero address; should succeed in reference
        bool success = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // The general rule: when newOwner is NOT zero, the call should NOT revert
        // (In the buggy version, it reverts for all newOwner != 0)
        assertTrue(newOwner == address(0) || !success == false, "Non-zero transferOwnership should not revert");
    }
}

