pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // skip if rewardToken already registered
        (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);
        vm.assume(lastUpdateTime == 0);

        try c.addReward(rewardToken) {
            // addReward succeeded; ensure owner() is not zero
            assertTrue(c.owner() != address(0));
        } catch {
            // addReward reverted; still owner() must never be zero
            assertTrue(c.owner() != address(0));
        }
    }
}

