pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(0x1234);
    address constant REWARD_DISTRIBUTOR = address(0x5678);

    function setUp() public {
        vm.prank(OWNER);
        c = new C(OWNER, REWARD_DISTRIBUTOR);
    }

    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Use prank(OWNER) so that onlyOwner functions work on the correct contract
        vm.prank(OWNER);
        c.addReward(rewardToken);
        // The general rule: the rewardDistributor must remain unchanged after addReward
        assertTrue(c.rewardDistributor() == REWARD_DISTRIBUTOR);
    }
}

