pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker1, address staker2, address rewardToken) public {
        vm.assume(staker1 != address(0) && staker2 != address(0) && staker1 != staker2);
        vm.assume(rewardToken != address(0) && rewardToken != address(this));

        // Ensure the reward token is added first (as per preconditions)
        c.addReward(rewardToken);

        // Store claimableRewards for both stakers before the call
        uint256 before1 = c.claimableRewards(staker1, rewardToken);
        uint256 before2 = c.claimableRewards(staker2, rewardToken);

        // Call addReward again (this will revert because reward already exists, but we catch)
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSignature("addReward(address)", rewardToken));

        // If it succeeded, check that sum of claimableRewards is unchanged
        if (success) {
            uint256 after1 = c.claimableRewards(staker1, rewardToken);
            uint256 after2 = c.claimableRewards(staker2, rewardToken);
            assertTrue(before1 + before2 == after1 + after2, "Sum of claimableRewards changed");
        } else {
            // If it reverted, no change is expected anyway
            assertTrue(true);
        }
    }
}

