// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account) public {
        vm.assume(account != address(this));
        uint256 balBefore = c.balanceOf(account);
        uint256 balZero = c.balanceOf(address(0));
        // The reference C correctly returns the balance of the account parameter.
        // For the buggy version, balanceOf(account) returns _balances[msg.sender],
        // which would be the test contract's balance, not account's.
        // Since account != address(this), the two balances should differ unless both are zero.
        assertTrue(balBefore != balZero || (balBefore == 0 && balZero == 0));
    }
}

