pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account1, address account2, uint256 amount) public {
        vm.assume(account1 != address(0) && account2 != address(0) && account1 != account2);
        vm.assume(amount > 0 && amount < 1e30);

        // Give both accounts the same balance of the staking token
        deal(address(c.stakingToken()), account1, amount);
        deal(address(c.stakingToken()), account2, amount);

        // Stake the same amount for both accounts
        vm.prank(account1);
        c.stake(amount);
        vm.prank(account2);
        c.stake(amount);

        // After staking, both should have the same balance because they staked the same
        uint256 balance1 = c.balanceOf(account1);
        uint256 balance2 = c.balanceOf(account2);

        assertTrue(balance1 == balance2, "balanceOf should return same value for accounts with same stake");
    }
}

