// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0));
        // Add the token once
        c.addReward(token);
        uint256 lenBefore = c.rewardTokens().length;
        // Try to add the same token again
        if (token != address(0)) {
            // In the reference, this call reverts; in the mutant it succeeds
            // We capture revert behavior
            (bool ok, ) = address(c).call(abi.encodeWithSelector(c.addReward.selector, token));
            uint256 lenAfter = c.rewardTokens().length;
            // General rule: adding the same token again must not change the array length
            // Reference: reverts so length unchanged; mutant: adds again so length increases
            assertTrue(!ok || lenAfter == lenBefore, "addReward should not extend array for duplicate token");
        }
    }
}

