// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        // Ensure token is not address(0) since addReward may behave differently
        vm.assume(token != address(0));

        // First call: should succeed on both reference and mutant
        c.addReward(token);
        uint256 lenAfterFirst = c.rewardTokensLength();

        // Second call: on reference it reverts, on mutant it succeeds
        bytes memory secondCallData = abi.encodeWithSelector(c.addReward.selector, token);
        (bool success, bytes memory) = address(c).call(secondCallData);

        // After the second call, measure the new length
        uint256 lenAfterSecond = c.rewardTokensLength();

        // The property: on the reference (success == false) the length stays same;
        // on the mutant (success == true) the length increases by 1.
        // We encode the rule as: length increased by exactly (success ? 1 : 0).
        assertTrue(lenAfterSecond == lenAfterFirst + (success ? 1 : 0));
    }
}

