// Actually we need to implement IERC20 on the test contract. That's allowed because the test contract can have additional functions.
contract InvMutTest is Test, IERC20 {
    C c;
    mapping(address => uint256) _balances;
    mapping(address => mapping(address => uint256)) _allowances;
    uint256 _totalSupply;

    function totalSupply() external view override returns (uint256) { return _totalSupply; }
    function balanceOf(address account) external view override returns (uint256) { return _balances[account]; }
    function transfer(address to, uint256 amount) external override returns (bool) {
        _balances[msg.sender] -= amount;
        _balances[to] += amount;
        return true;
    }
    function allowance(address owner, address spender) external view override returns (uint256) { return _allowances[owner][spender]; }
    function approve(address spender, uint256 amount) external override returns (bool) {
        _allowances[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        _allowances[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }

    function setUp() public {
        c = new C(address(this), address(this));
        // mint some tokens to the test contract itself (for staking? No, staker needs tokens)
    }

    function testFuzz_property(address staker, uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.assume(staker != address(0));
        vm.assume(staker != address(c));

        // give tokens to staker
        _balances[staker] += amount;

        uint256 supplyBefore = c.totalSupply();
        uint256 contractBalanceBefore = _balances[address(c)];

        // stake from staker
        vm.prank(staker);
        c.stakeFor(staker, amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 contractBalanceAfter = _balances[address(c)];

        // The invariant: the increase in total supply should equal the increase in contract staking token balance
        assertTrue(supplyAfter - supplyBefore == contractBalanceAfter - contractBalanceBefore, "Total supply does not match contract balance");
    }
}

