pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0));
        vm.assume(token != address(this));
        vm.assume(token.code.length == 0);

        // Add one reward token
        address addedToken = address(0x1234);
        c.addReward(addedToken);

        // Try to notify reward for a token that was never added
        bool reverted = false;
        try c.notifyRewardAmount(token, 1e18) {
            // should not succeed if token != addedToken
            if (token != addedToken) {
                reverted = true;
            }
        } catch {
            reverted = true;
        }

        // The rule: if token was not added, notifyRewardAmount must revert
        assertTrue(token != addedToken ? reverted : true);
    }
}

