pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address oldStaking) public {
        vm.assume(oldStaking != address(0) && oldStaking != address(c));
        c.addReward(address(0x1));

        // Record total supply before potential migration
        uint256 totalSupplyBefore = c.totalSupply();

        // Attempt to migrate from oldStaking (which doesn't have staked tokens)
        // The buggy version will try to withdraw from address(0), which will revert
        // because address(0) has no balance. The correct version reverts for the
        // same reason (oldStaking has no balance).
        // Use try/catch to handle reverts
        try c.migrateStake(oldStaking, 1) {
            // If migrate succeeds, totalSupply must have increased by 1
            assertTrue(c.totalSupply() == totalSupplyBefore + 1, "totalSupply should increase by 1");
        } catch {
            // If it reverts, totalSupply must remain unchanged
            assertTrue(c.totalSupply() == totalSupplyBefore, "totalSupply should not change");
        }
    }
}

